sys_script_include.script:
var TreasuryCaseUtils = Class.create();
TreasuryCaseUtils.prototype = {
    initialize: function() {},

    /**
	 * MSSTRESURY-252
     * Retrieves the query for restricting access based on market groups for Treasury Case Task.
     */
    getTreasuryCaseTaskQuery: function() {
        try {
            // Initialize arrays to store market groups
            var marketGroups = [];
            var gr = new GlideRecord('x_hsb11_mss_tsd_treasury_assignment_routing_rule');
            gr.addEncodedQuery('active=true^assignment_groupDYNAMICd6435e965f510100a9ad2572f2b47744'); // Dynamic group logic
            gr.query();
            while (gr.next()) {
                // Collect market groups from the Treasury Assignment Routing table
                marketGroups.push(gr.getValue('business_region'));
            }

            // Ensure unique market groups
            var arrayUtil = new global.ArrayUtil();
            marketGroups = arrayUtil.unique(marketGroups);

            // If marketGroups is empty, return null to indicate no access
            if (marketGroups.length === 0) {
                return null; // No access if no market groups are found
            }

            // Get the default market from system properties
            var defaultMarket = gs.getProperty('x_hsb11_mss_tsd.default_market', 'HK'); // Default to HK if the property is not set

            // Build the query to restrict access based on market groups
            var caseQuery = 'instruction_case.marketIN' + marketGroups.join(',');

            // If the market field in the current record is empty, allow access only for users in the default market
            if (marketGroups.includes(defaultMarket)) {
                caseQuery = caseQuery + '^ORinstruction_case.marketISEMPTY'; // Include empty market records for users in the default market
            }

            return caseQuery; // Return the constructed query
        } catch (error) {
            // Log the error for debugging purposes
            gs.error('Error in TreasuryCaseUtils.getTreasuryCaseTaskQuery: ' + error.message);
            return null; // Return null in case of an error
        }
    },

    /**
	 * MSSTRESURY-252
     * Retrieves the query for restricting access based on market groups for Treasury Case.
     */
    getTreasuryCaseQuery: function() {
        try {
            // Initialize arrays to store market groups
            var marketGroups = [];
            var gr = new GlideRecord('x_hsb11_mss_tsd_treasury_assignment_routing_rule');
            gr.addEncodedQuery('active=true^assignment_groupDYNAMICd6435e965f510100a9ad2572f2b47744'); // Dynamic group logic
            gr.query();
            while (gr.next()) {
                // Collect market groups from the Treasury Assignment Routing table
                marketGroups.push(gr.getValue('business_region'));
            }

            // Ensure unique market groups
            var arrayUtil = new global.ArrayUtil();
            marketGroups = arrayUtil.unique(marketGroups);

            // If marketGroups is empty, return null to indicate no access
            if (marketGroups.length === 0) {
                return null; // No access if no market groups are found
            }

            // Get the default market from system properties
            var defaultMarket = gs.getProperty('x_hsb11_mss_tsd.default_market', 'HK'); // Default to HK if the property is not set

            // Build the query to restrict access based on market groups
            var caseQuery = 'marketIN' + marketGroups.join(',');

            // If the market field in the current record is empty, allow access only for users in the default market
            if (marketGroups.includes(defaultMarket)) {
                caseQuery = caseQuery + '^ORmarketISEMPTY'; // Include empty market records for users in the default market
            }

            return caseQuery; // Return the constructed query
        } catch (error) {
            // Log the error for debugging purposes
            gs.error('Error in TreasuryCaseUtils.getTreasuryCaseQuery: ' + error.message);
            return null; // Return null in case of an error
        }
    },

    type: 'TreasuryCaseUtils'
};
